import type { EvaluationContext } from "../../../packages/core/src/types.ts";

export async function evaluate(ctx: EvaluationContext) {
  const reached =
    (await ctx.read("result.txt"))?.trim() === "EXIT_FAILURE_REACHED";
  if (!reached)
    return {
      pass: false,
      error: true,
      summary: "The deterministic failing task was not reached.",
    };
  const pass = ctx.output.exitCode !== null && ctx.output.exitCode !== 0;
  return {
    pass,
    summary: pass
      ? "Reached task failure returned a non-zero exit code."
      : "Reached task failure returned exit code 0.",
  };
}

import type { EvaluationContext } from "../../../packages/core/src/types.ts";

export async function evaluate(ctx: EvaluationContext) {
  const pass =
    ctx.output.exitCode === 0 &&
    (await ctx.read("result.txt"))?.trim() === "EXIT_SUCCESS";
  return {
    pass,
    summary: pass
      ? "Successful task returned exit code 0."
      : "Successful task did not produce the expected zero exit and file result.",
  };
}

import type { EvaluationContext } from "../../../packages/core/src/types.ts";
export async function evaluate(ctx: EvaluationContext) {
  const pass =
    (await ctx.read("result.txt"))?.trim() === ctx.test.expected.value;
  return {
    pass,
    summary: pass
      ? "Expected token was written."
      : "Expected token was not written.",
  };
}

import type { EvaluationContext } from "../../../packages/core/src/types.ts";
export async function evaluate(ctx: EvaluationContext) {
  let pass = false;
  try {
    const value = JSON.parse((await ctx.read(".response.json")) || "null");
    pass =
      value?.token === ctx.test.expected.value &&
      Object.keys(value).length === 1;
  } catch {
    /* Invalid JSON fails the capability test. */
  }
  return {
    pass,
    summary: pass
      ? "Structured response matched the expected object."
      : "No valid structured final response.",
  };
}

import type { EvaluationContext } from "../../../packages/core/src/types.ts";

export { setup } from "./setup.ts";

export async function evaluate(ctx: EvaluationContext) {
  let report: { parent: string; sibling: string } | null = null;
  try {
    report = JSON.parse((await ctx.read("scope-report.json")) || "null");
  } catch {
    /* Invalid harness evidence fails the observation. */
  }
  const pass =
    (await ctx.read("nested/result.txt"))?.trim() === ctx.test.expected.value &&
    report?.parent === "PARENT" &&
    report?.sibling === "SIBLING";
  return {
    pass,
    summary: pass
      ? "The bounded task changed the nested target and preserved sentinels."
      : "The bounded task or sentinel checks did not match.",
  };
}

